// --- Resource Indexers (__index) ---

static int rl_AudioStream_index(lua_State *L)
{
    RLUA_Handle *h = (RLUA_Handle *)luaL_checkudata(L, 1, "AudioStream");
    if (lua_isnumber(L, 2)) {
        int i = lua_tointeger(L, 2) - 1;
        if (i < 0 || i >= h->count) return luaL_error(L, "index out of bounds");
        AudioStream *ptr = &((AudioStream *)h->data)[i];
        RLUA_PUSH_View(L, ptr, 1, "AudioStream", false);
        return 1;
    }
    const char *key = luaL_checkstring(L, 2);
    AudioStream *data = (AudioStream *)h->data;
    if (strcmp(key, "buffer") == 0) { // Pointer to internal data used by the audio system
        lua_pushlightuserdata(L, data->buffer);
        return 1;
    }
    if (strcmp(key, "processor") == 0) { // Pointer to internal data processor, useful for audio effects
        lua_pushlightuserdata(L, data->processor);
        return 1;
    }
    if (strcmp(key, "sampleRate") == 0) { // Frequency (samples per second)
        lua_pushinteger(L, data->sampleRate);
        return 1;
    }
    if (strcmp(key, "sampleSize") == 0) { // Bit depth (bits per sample): 8, 16, 32 (24 not supported)
        lua_pushinteger(L, data->sampleSize);
        return 1;
    }
    if (strcmp(key, "channels") == 0) { // Number of channels (1-mono, 2-stereo, ...)
        lua_pushinteger(L, data->channels);
        return 1;
    }
    return 0;
}

