static int rl_Mesh_index(lua_State *L)
{
    RLUA_Handle *h = (RLUA_Handle *)luaL_checkudata(L, 1, "Mesh");
    if (lua_isnumber(L, 2)) {
        int i = lua_tointeger(L, 2) - 1;
        if (i < 0 || i >= h->count) return luaL_error(L, "index out of bounds");
        Mesh *ptr = &((Mesh *)h->data)[i];
        RLUA_PUSH_View(L, ptr, 1, "Mesh", false);
        return 1;
    }
    const char *key = luaL_checkstring(L, 2);
    Mesh *data = (Mesh *)h->data;
    if (strcmp(key, "vertexCount") == 0) { // Number of vertices stored in arrays
        lua_pushinteger(L, data->vertexCount);
        return 1;
    }
    if (strcmp(key, "triangleCount") == 0) { // Number of triangles stored (indexed or not)
        lua_pushinteger(L, data->triangleCount);
        return 1;
    }
    if (strcmp(key, "vertices") == 0) { // Vertex position (XYZ - 3 components per vertex) (shader-location = 0)
        lua_pushlightuserdata(L, data->vertices);
        return 1;
    }
    if (strcmp(key, "texcoords") == 0) { // Vertex texture coordinates (UV - 2 components per vertex) (shader-location = 1)
        lua_pushlightuserdata(L, data->texcoords);
        return 1;
    }
    if (strcmp(key, "texcoords2") == 0) { // Vertex texture second coordinates (UV - 2 components per vertex) (shader-location = 5)
        lua_pushlightuserdata(L, data->texcoords2);
        return 1;
    }
    if (strcmp(key, "normals") == 0) { // Vertex normals (XYZ - 3 components per vertex) (shader-location = 2)
        lua_pushlightuserdata(L, data->normals);
        return 1;
    }
    if (strcmp(key, "tangents") == 0) { // Vertex tangents (XYZW - 4 components per vertex) (shader-location = 4)
        lua_pushlightuserdata(L, data->tangents);
        return 1;
    }
    if (strcmp(key, "colors") == 0) { // Vertex colors (RGBA - 4 components per vertex) (shader-location = 3)
        lua_pushlightuserdata(L, data->colors);
        return 1;
    }
    if (strcmp(key, "indices") == 0) { // Vertex indices (in case vertex data comes indexed)
        lua_pushlightuserdata(L, data->indices);
        return 1;
    }
    if (strcmp(key, "boneCount") == 0) { // Number of bones (MAX: 256 bones)
        lua_pushinteger(L, data->boneCount);
        return 1;
    }
    if (strcmp(key, "boneIndices") == 0) { // Vertex bone indices, up to 4 bones influence by vertex (skinning) (shader-location = 6)
        lua_pushlightuserdata(L, data->boneIndices);
        return 1;
    }
    if (strcmp(key, "boneWeights") == 0) { // Vertex bone weight, up to 4 bones influence by vertex (skinning) (shader-location = 7)
        lua_pushlightuserdata(L, data->boneWeights);
        return 1;
    }
    if (strcmp(key, "animVertices") == 0) { // Animated vertex positions (after bones transformations)
        lua_pushlightuserdata(L, data->animVertices);
        return 1;
    }
    if (strcmp(key, "animNormals") == 0) { // Animated normals (after bones transformations)
        lua_pushlightuserdata(L, data->animNormals);
        return 1;
    }
    if (strcmp(key, "vaoId") == 0) { // OpenGL Vertex Array Object id
        lua_pushinteger(L, data->vaoId);
        return 1;
    }
    if (strcmp(key, "vboId") == 0) { // OpenGL Vertex Buffer Objects id (default vertex data)
        lua_pushlightuserdata(L, data->vboId);
        return 1;
    }
    return 0;
}

