// --- Wrappers ---

// Callbacks to hook some internal functions
// WARNING: These callbacks are intended for advanced users

// Window-related functions
// Initialize window and OpenGL context
static int rl_InitWindow(lua_State *L)
{
    int width = (int)luaL_checkinteger(L, 1);
    int height = (int)luaL_checkinteger(L, 2);
    const char * title = luaL_checkstring(L, 3);
    InitWindow(width, height, title);
    return 0;
}

// Close window and unload OpenGL context
static int rl_CloseWindow(lua_State *L)
{
    CloseWindow();
    return 0;
}

// Check if application should close (KEY_ESCAPE pressed or windows close icon clicked)
static int rl_WindowShouldClose(lua_State *L)
{
    bool result = WindowShouldClose();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window has been initialized successfully
static int rl_IsWindowReady(lua_State *L)
{
    bool result = IsWindowReady();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window is currently fullscreen
static int rl_IsWindowFullscreen(lua_State *L)
{
    bool result = IsWindowFullscreen();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window is currently hidden
static int rl_IsWindowHidden(lua_State *L)
{
    bool result = IsWindowHidden();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window is currently minimized
static int rl_IsWindowMinimized(lua_State *L)
{
    bool result = IsWindowMinimized();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window is currently maximized
static int rl_IsWindowMaximized(lua_State *L)
{
    bool result = IsWindowMaximized();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window is currently focused
static int rl_IsWindowFocused(lua_State *L)
{
    bool result = IsWindowFocused();
    lua_pushboolean(L, result);
    return 1;
}

// Check if window has been resized last frame
static int rl_IsWindowResized(lua_State *L)
{
    bool result = IsWindowResized();
    lua_pushboolean(L, result);
    return 1;
}

// Check if one specific window flag is enabled
static int rl_IsWindowState(lua_State *L)
{
    unsigned int flag = (unsigned int)luaL_checkinteger(L, 1);
    bool result = IsWindowState(flag);
    lua_pushboolean(L, result);
    return 1;
}

// Set window configuration state using flags
static int rl_SetWindowState(lua_State *L)
{
    unsigned int flags = (unsigned int)luaL_checkinteger(L, 1);
    SetWindowState(flags);
    return 0;
}

