static int rl_GetCollisionRec(lua_State *L)
{
    Rectangle rec1 = RLUA_CHECK_Rectangle(L, 1);
    Rectangle rec2 = RLUA_CHECK_Rectangle(L, 2);
    Rectangle result = GetCollisionRec(rec1, rec2);
    RLUA_PUSH_Rectangle(L, result);
    return 1;
}

